<script setup>
import { deviceChoices } from '../../deviceCatalog.js'
import DeviceSelect from '../DeviceSelect.vue'
import { computed,onBeforeUnmount,reactive,ref } from 'vue'
import { apiAll } from '../../api.js'
import { can } from '../../permissions.js'
import { createClientId } from '../../clientId.js'
import { maintenanceWrite } from '../../maintenance/api.js'
import { contextKinds,stateLabel,maintenanceTime,revisionEnvelope,evidencePayload,decimal,money } from '../../maintenance/helpers.js'
import MaintenanceEvidence from './MaintenanceEvidence.vue'
const props=defineProps({devices:Array,assets:Array,records:Array,contexts:Array,admissions:Array,faults:Array,costs:Array,deviceId:String})
const emit=defineEmits(['refresh','navigate'])
const type=ref('maintenance-contexts'),dialog=ref(false),busy=ref(false),error=ref(''),key=ref(''),alarms=ref([]),form=reactive({})
let generation=0,disposed=false
const evDevices=computed(()=>deviceChoices(form.deviceIds||[],props.devices)),sourceRows=computed(()=>form.sourceKind==='ASSET_INSTANCE'?props.assets:props.records),rows=computed(()=>({ 'maintenance-contexts':props.contexts,'maintenance-admissions':props.admissions,'maintenance-fault-cycles':props.faults,'maintenance-costs':props.costs}[type.value]||[]).filter(row=>!props.deviceId||row.deviceIds.includes(props.deviceId)))
const titles={'maintenance-contexts':'工况记录','maintenance-admissions':'比较准入参数','maintenance-fault-cycles':'同类故障核实','maintenance-costs':'支出与未来报价'}
function edit(row){const b=row?.body||{};Object.assign(form,{resourceId:row?.resourceId||createClientId(),expectedVersion:row?.version||0,deviceIds:[...(row?.deviceIds|| (props.deviceId?[props.deviceId]:[]))],kind:b.kind||'OPERATING_INTENSITY',range:b.start?[b.start,b.end]:null,intensity:b.intensity||'',reason:b.reason||'',confirmed:!!b.confirmed,evidence:(b.evidence||[]).map(r=>({...r})),faultType:b.faultType||'',parameterVersion:b.parameters?.version||'',minimumEffectiveHours:b.parameters?.minimumEffectiveHours??null,minimumObservationCoverage:b.parameters?.minimumObservationCoverage??null,minimumFaultSourceCoverage:b.parameters?.minimumFaultSourceCoverage??null,minimumConfirmedCycles:b.parameters?.minimumConfirmedCycles??null,postMaintenanceWaitMs:b.parameters?.postMaintenanceWaitMs??null,comparableContextRequired:b.parameters?.comparableContextRequired??true,alarmId:b.alarmId||'',faultClass:b.classification||'UNKNOWN',cycleType:b.type||'FAULT',basis:b.basis||'',sourceKind:b.sourceKind||'ASSET_INSTANCE',sourceId:b.sourceId||'',costType:b.type==='ACTUAL'?'ACTUAL':'ESTIMATE',currency:b.currency||'CNY',material:b.material??'',labor:b.labor??'',externalService:b.externalService??'',laborHours:b.laborHours??'',occurredAt:b.occurredAt??null,planning:b.planningStart?[b.planningStart,b.planningEnd]:null});key.value=createClientId();error.value='';dialog.value=true;loadAlarms()}
async function loadAlarms(){alarms.value=[];if(type.value!=='maintenance-fault-cycles'||form.deviceIds.length!==1||!can('menu:alarms'))return;const token=generation;try{const v=await apiAll('/api/v1/alarms?'+new URLSearchParams({deviceId:form.deviceIds[0]}));if(token===generation&&!disposed)alarms.value=v.items||[]}catch(cause){error.value=cause.message}}
function sourceChanged(){const source=sourceRows.value.find(row=>row.resourceId===form.sourceId);if(source)form.deviceIds=[...source.deviceIds];form.evidence=[]}
async function save(){if(busy.value)return;const token=generation;busy.value=true;error.value='';try{if(!form.deviceIds.length)throw Error('请明确实际设备范围');let body;if(type.value==='maintenance-contexts'){if(!form.range?.[0]||!(form.range[1]>form.range[0])||!form.reason.trim())throw Error('请填写实际工况区间和依据');body={kind:form.kind,start:form.range[0],end:form.range[1],intensity:form.kind==='OPERATING_INTENSITY'?form.intensity.trim():'',reason:form.reason.trim(),confirmed:form.confirmed,evidence:evidencePayload(form.evidence,form.deviceIds)}}else if(type.value==='maintenance-admissions'){if(!form.faultType.trim()||!form.parameterVersion.trim()||[form.minimumEffectiveHours,form.minimumObservationCoverage,form.minimumFaultSourceCoverage,form.minimumConfirmedCycles,form.postMaintenanceWaitMs].some(v=>v==null))throw Error('准入要求须人工明确填写，未知不能以默认值代替');body={faultType:form.faultType.trim(),parameters:{version:form.parameterVersion.trim(),minimumEffectiveHours:form.minimumEffectiveHours,minimumObservationCoverage:form.minimumObservationCoverage,minimumFaultSourceCoverage:form.minimumFaultSourceCoverage,minimumConfirmedCycles:form.minimumConfirmedCycles,postMaintenanceWaitMs:form.postMaintenanceWaitMs,comparableContextRequired:form.comparableContextRequired}}}else if(type.value==='maintenance-fault-cycles'){const alarm=alarms.value.find(row=>row.id===form.alarmId);if(!alarm||!form.basis.trim())throw Error('请选择具体实际周期并填写核实依据');body={alarmId:alarm.id,deviceId:alarm.deviceId,componentId:alarm.componentId||'',type:form.cycleType,classification:form.faultClass,basis:form.basis.trim(),status:'DRAFT',evidence:evidencePayload(form.evidence,form.deviceIds)}}else{if(!form.sourceId||!form.basis.trim()||!form.occurredAt||!form.planning?.[0]||!(form.planning[1]>form.planning[0]))throw Error('费用须绑定实际来源、币种、报价日期与同口径规划期');body={sourceKind:form.sourceKind,sourceId:form.sourceId,type:form.costType,currency:form.currency.toUpperCase(),occurredAt:form.occurredAt,planningStart:form.planning[0],planningEnd:form.planning[1],basis:form.basis.trim(),evidence:evidencePayload(form.evidence,form.deviceIds)};for(const field of ['material','labor','externalService','laborHours']){const value=decimal(form[field]);if(value!==null)body[field]=value}}await maintenanceWrite(type.value,'','',revisionEnvelope(form,body,key.value));if(token!==generation||disposed)return;dialog.value=false;emit('refresh')}catch(cause){if(token===generation)error.value=cause.status===409?'资料版本已变化，请刷新后重新核对。':cause.message}finally{if(token===generation)busy.value=false}}
async function confirm(row){if(busy.value)return;busy.value=true;error.value='';try{await maintenanceWrite('maintenance-fault-cycles',row.resourceId,'confirm',{expectedVersion:row.version,idempotencyKey:createClientId()});emit('refresh')}catch(cause){error.value=cause.message}finally{busy.value=false}}
onBeforeUnmount(()=>{disposed=true;generation++})
</script>
<template><section class="maintenance-stack"><div class="maintenance-toolbar"><ui-select v-model="type"><ui-option v-for="(title,id) in titles" :key="id" :value="id" :label="title" :disabled="id==='maintenance-costs'&&!can('GET /api/v1/maintenance-costs')"/></ui-select><ui-button v-if="can('POST /api/v1/'+type)" size="small" type="primary" @click="edit()">登记{{titles[type]}}</ui-button></div><p class="maintenance-hint">排除仅使用有依据并已确认的停运、测试或平台不可用区间；设备离线留在有效分母。准入要求仅支持描述性比较。金额未知保留空白。</p><ui-alert v-if="error&&!dialog" :title="error" type="error" :closable="false"/><div class="maintenance-table-scroll"><ui-table :data="rows" empty-text="此范围尚无相应资料。"><ui-table-column label="资料 / 固定版本" min-width="230"><template #default="{row}">{{row.body.kind?contextKinds[row.body.kind]:row.body.faultType||row.body.basis}}<p class="maintenance-meta">版本 {{row.version}} · {{row.deviceIds.map(id=>devices.find(d=>d.id===id)?.name||id).join('、')}}</p><span v-if="type==='maintenance-fault-cycles'">{{stateLabel(row.body.type)}} · {{stateLabel(row.body.classification)}} · {{stateLabel(row.body.status)}}</span></template></ui-table-column><ui-table-column label="区间 / 参数 / 金额" min-width="340"><template #default="{row}"><template v-if="type==='maintenance-contexts'">{{maintenanceTime(row.body.start)}} 至 {{maintenanceTime(row.body.end)}}<p class="maintenance-meta">{{row.body.intensity}} · {{row.body.confirmed?'人工已确认':'未确认'}} · {{row.body.reason}}</p></template><template v-else-if="type==='maintenance-admissions'">最低 {{row.body.parameters.minimumEffectiveHours}} 小时 · 覆盖 {{row.body.parameters.minimumObservationCoverage}} · 故障来源覆盖 {{row.body.parameters.minimumFaultSourceCoverage}}<p class="maintenance-meta">确认周期 {{row.body.parameters.minimumConfirmedCycles}} · 后等待 {{row.body.parameters.postMaintenanceWaitMs}} ms · {{row.body.parameters.version}}</p></template><template v-else-if="type==='maintenance-costs'">{{stateLabel(row.body.type)}} · {{row.body.currency}}<p class="maintenance-meta">材料 {{money(row.body.material)}} · 人工 {{money(row.body.labor)}} · 外部服务 {{money(row.body.externalService)}} · 工时 {{money(row.body.laborHours)}}<br>{{maintenanceTime(row.body.planningStart)}} 至 {{maintenanceTime(row.body.planningEnd)}}</p></template><template v-else>{{row.body.basis}}<p class="maintenance-meta">{{row.body.confirmedBy}} · {{maintenanceTime(row.body.confirmedAt)}}</p></template></template></ui-table-column><ui-table-column label="操作" width="180"><template #default="{row}"><ui-button v-if="can('POST /api/v1/'+type)&&!(type==='maintenance-fault-cycles'&&row.body.status==='CONFIRMED')" text size="small" @click="edit(row)">补充新版本</ui-button><ui-button v-if="type==='maintenance-fault-cycles'&&row.body.status==='DRAFT'&&can('POST /api/v1/maintenance-fault-cycles/:id/confirm')" text size="small" :loading="busy" @click="confirm(row)">确认同类周期</ui-button></template></ui-table-column></ui-table></div>
<ui-dialog v-model="dialog" :title="'登记'+titles[type]" width="min(920px,94vw)" :close-on-click-modal="false"><div class="maintenance-dialog-body maintenance-stack"><ui-alert v-if="error" :title="error" type="error" :closable="false"/><ui-form label-position="top" :disabled="busy"><ui-form-item v-if="type!=='maintenance-costs'" label="明确设备范围" required><DeviceSelect v-model="form.deviceIds" multiple :disabled="!!form.expectedVersion||!!deviceId" @change="form.evidence=[];loadAlarms()"/></ui-form-item><template v-if="type==='maintenance-contexts'"><ui-form-item label="工况类型" required><ui-select v-model="form.kind"><ui-option v-for="(label,id) in contextKinds" :key="id" :value="id" :label="label"/></ui-select></ui-form-item><ui-form-item label="实际工况区间" required><ui-date-range v-model="form.range"/></ui-form-item><ui-form-item v-if="form.kind==='OPERATING_INTENSITY'" label="实际运行强度与口径" required><ui-input v-model="form.intensity" placeholder="有实际依据的运行强度描述"/></ui-form-item><ui-form-item label="工况依据" required><ui-input v-model="form.reason" type="textarea"/></ui-form-item><ui-checkbox v-model="form.confirmed">根据关联证据确认此工况</ui-checkbox></template><template v-else-if="type==='maintenance-admissions'"><div class="maintenance-grid"><ui-form-item label="同类故障类型" required><ui-input v-model="form.faultType" :disabled="!!form.expectedVersion"/></ui-form-item><ui-form-item label="单位参数版本" required><ui-input v-model="form.parameterVersion"/></ui-form-item><ui-form-item label="最低有效观察小时" required><ui-input-number v-model="form.minimumEffectiveHours" :min="0"/></ui-form-item><ui-form-item label="最低观测覆盖（0—1）" required><ui-input-number v-model="form.minimumObservationCoverage" :min="0" :max="1" :step="0.1"/></ui-form-item><ui-form-item label="最低故障来源覆盖（0—1）" required><ui-input-number v-model="form.minimumFaultSourceCoverage" :min="0" :max="1" :step="0.1"/></ui-form-item><ui-form-item label="最低确认同类周期数" required><ui-input-number v-model="form.minimumConfirmedCycles" :min="0" :precision="0"/></ui-form-item><ui-form-item label="维修后等待毫秒" required><ui-input-number v-model="form.postMaintenanceWaitMs" :min="0" :precision="0"/></ui-form-item></div><ui-checkbox v-model="form.comparableContextRequired">要求前后工况同口径</ui-checkbox></template><template v-else-if="type==='maintenance-fault-cycles'"><ui-form-item label="具体实际告警周期" required><ui-select v-model="form.alarmId" :disabled="!!form.expectedVersion"><ui-option v-for="a in alarms" :key="a.id" :value="a.id" :label="`${a.content||a.alarmType} · ${maintenanceTime(a.timestamp||a.createdAt)}`"/></ui-select></ui-form-item><div class="maintenance-grid"><ui-form-item label="实际周期类型" required><ui-select v-model="form.cycleType"><ui-option v-for="t in ['FAULT','FIRE','OTHER']" :key="t" :value="t" :label="stateLabel(t)"/></ui-select></ui-form-item><ui-form-item label="具体来源分类" required><ui-select v-model="form.faultClass"><ui-option v-for="t in ['PRODUCTION','TEST','UNKNOWN']" :key="t" :value="t" :label="stateLabel(t)"/></ui-select></ui-form-item></div><ui-form-item label="实际核实依据" required><ui-input v-model="form.basis" type="textarea"/></ui-form-item></template><template v-else><div class="maintenance-grid"><ui-form-item label="费用来源类型" required><ui-select v-model="form.sourceKind" :disabled="!!form.expectedVersion" @change="form.sourceId=''"><ui-option value="ASSET_INSTANCE" label="实物实例（未来报价）"/><ui-option value="MAINTENANCE_RECORD" label="维修记录（已发生支出）"/></ui-select></ui-form-item><ui-form-item label="具体来源" required><ui-select v-model="form.sourceId" :disabled="!!form.expectedVersion" @change="sourceChanged"><ui-option v-for="r in sourceRows" :key="r.resourceId" :value="r.resourceId" :label="r.body.name"/></ui-select></ui-form-item><ui-form-item label="费用类型" required><ui-select v-model="form.costType"><ui-option value="ESTIMATE" label="未来估算或报价"/><ui-option value="ACTUAL" label="已发生支出"/></ui-select></ui-form-item><ui-form-item label="明确单一币种" required><ui-input v-model="form.currency" maxlength="3"/></ui-form-item><ui-form-item v-for="[field,label] in [['material','材料金额'],['labor','人工金额'],['externalService','外部服务金额'],['laborHours','实际工时（不自动折算金额）']]" :key="field" :label="label"><ui-input v-model="form[field]" placeholder="未知保留空白，精确十进制"/></ui-form-item><ui-form-item label="发生或报价日期" required><ui-date-time v-model="form.occurredAt" disable-future/></ui-form-item></div><ui-form-item label="同口径规划范围" required><ui-date-range v-model="form.planning"/></ui-form-item><ui-form-item label="费用依据" required><ui-input v-model="form.basis" type="textarea"/></ui-form-item></template><MaintenanceEvidence v-if="type!=='maintenance-admissions'" v-model="form.evidence" :devices="evDevices" :disabled="busy"/></ui-form></div><template #footer><ui-button :disabled="busy" @click="dialog=false">取消</ui-button><ui-button type="primary" :loading="busy" @click="save">保存有依据版本</ui-button></template></ui-dialog></section></template>
